const n=api.seg(t,0.3,4);
for(let i=0;i<12;i++){
  const kk=api.stag(t,i,{gap:0.25,dur:0.5,from:0.3});
  const x=60+(i%4)*90, y=200+Math.floor(i/4)*110;
  api.shape('house',x+10,y,46,{c:'fg',fill:'a2',k:kk});
  api.shape('heart',x+10,y-8,16,{c:'ink',fill:'ink',k:kk});
}
api.counter(Math.round(n*100),cx,540,{k:1,suf:' homes',size:40,pre:''});
api.text('x $29 each month',cx,600,{size:22,align:'center',k:api.seg(t,3,4.2)});
api.arrow(cx,625,cx,700,{k:api.seg(t,4,5),c:'accent'});
