api.look('agent');
const cx=api.w/2, cy=330;
const parts=[{l:'Toys $9',v:9,c:'a2'},{l:'Box + ship $8',v:8,c:'a3'},{l:'Shelter gift $4',v:4,c:'good'},{l:'Profit $8',v:8,c:'accent'}];
api.donut(parts.map(p=>({v:p.v,c:p.c})),cx,cy,130,{k:api.seg(t,0,2)});
api.text('$29',cx,cy-16,{size:44,align:'center',weight:700,k:api.seg(t,0.5,1.5)});
parts.forEach((p,i)=>{
  const kk=api.stag(t,i,{gap:0.7,dur:0.6,from:2});
  const y=530+i*38;
  api.dot(70,y,8,{k:kk,c:p.c});
  api.text(p.l,92,y-10,{size:20,k:kk});
});
api.say('Each box splits four ways',0.4,6.5);

